<script setup lang="ts">import {computed} from "vue";import type {VersionSummaryViewModel} from "~/types/account-version-summary";import StorySlideShell from "../StorySlideShell.vue";const p=defineProps<{summary:VersionSummaryViewModel;pageIndex:number;pageTotal:number;active:boolean;reducedMotion:boolean}>();const max=computed(()=>Math.max(...(p.summary.weekdayActivity?.counts||[1]),1));</script>
<template><StorySlideShell :page-index="pageIndex" :page-total="pageTotal" :eyebrow="summary.copy.weekdayActivity.eyebrow" :title="summary.copy.weekdayActivity.title" :lead="summary.copy.weekdayActivity.body" tone="aurora" :active="active" :reduced-motion="reducedMotion"><div v-if="summary.weekdayActivity" class="week"><div class="bars" data-animate><div v-for="(count,i) in summary.weekdayActivity.counts" :key="i" :class="{top:i===summary.weekdayActivity.topWeekday,bottom:i===summary.weekdayActivity.bottomWeekday}"><span><i :style="{height:`${Math.max(8,count/max*100)}%`}"></i></span><strong>{{summary.weekdayActivity.labels[i]}}</strong><small>{{count}}</small></div></div><div class="facts"><article data-animate><span>最常游玩</span><strong>{{summary.weekdayActivity.topLabel}}</strong></article><article data-animate><span>最少游玩</span><strong>{{summary.weekdayActivity.bottomLabel}}</strong></article></div></div></StorySlideShell></template>
